package tracking;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Small helpers used by the nightly jobs. */
public final class Ops {
    private Ops() {}

    public static <T> List<T> repeatVisitors(List<T> visits) {
        List<T> out = new ArrayList<>();
        for (T item : visits) {
            if (Collections.frequency(visits, item) > 1 && !out.contains(item)) {
                out.add(item);
            }
        }
        return out;
    }
}

