package gatehouse;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Small helpers used by the nightly jobs. */
public final class Ops {
    private Ops() {}

    public static <T> List<T> missingParts(List<T> required, List<T> onHand) {
        Set<T> blockedSet = new HashSet<>(onHand);
        List<T> out = new ArrayList<>();
        for (T item : required) {
            if (!blockedSet.contains(item)) {
                out.add(item);
            }
        }
        return out;
    }
}

