package tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Small helpers used by the nightly jobs. */
public final class Ops {
    private Ops() {}

    public static <T> List<Integer> slotNumbers(List<T> shelf, List<T> requests) {
        Map<T, Integer> first = new HashMap<>();
        for (int i = 0; i < shelf.size(); i++) {
            first.putIfAbsent(shelf.get(i), i);
        }
        List<Integer> out = new ArrayList<>();
        for (T needle : requests) {
            out.add(first.getOrDefault(needle, -1));
        }
        return out;
    }
}

