package gatehouse;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Small helpers used by the nightly jobs. */
public final class Ops {
    private Ops() {}

    public static <T> List<Integer> columnIndexes(List<T> header, List<T> wanted) {
        Map<T, Integer> first = new HashMap<>();
        for (int i = 0; i < header.size(); i++) {
            first.putIfAbsent(header.get(i), i);
        }
        List<Integer> out = new ArrayList<>();
        for (T needle : wanted) {
            out.add(first.getOrDefault(needle, -1));
        }
        return out;
    }
}

